powerpagecomponent.content:
{
  "source": "{%- comment -%}
components--web-nav-header
DSR TEMPORARY MENU (commented out original below)
{%- endcomment -%}

<ul class="hit-nav__menu" role="list">
  <li class="hit-nav__item">
    <a href="https://www.dsr.org.au/" class="hit-nav__link">DSR Home</a>
  </li>
</ul>

{%- comment -%}
===========================================
ORIGINAL MENU CODE (TEMPORARILY DISABLED)
===========================================

{%- assign DEBUG = false -%}
{%- if request.params.navdebug == '1' -%}{%- assign DEBUG = true -%}{%- endif -%}

{%- assign headerMenuLocationValue = 815390000 -%}

{%- comment -%}
Fetch active header menu
{%- endcomment -%}
{%- fetchxml navMenu -%}
<fetch top="1" mapping="logical">
  <entity name="hit_webnavmenu">
    <attribute name="hit_webnavmenuid" />
    <filter>
      <condition attribute="hit_isactive" operator="eq" value="1" />
      <condition attribute="hit_website" operator="eq" value="{{ website.id | escape }}" />
      <condition attribute="hit_menulocation" operator="eq" value="{{ headerMenuLocationValue }}" />
    </filter>
  </entity>
</fetch>
{%- endfetchxml -%}

{%- assign menuRecord = navMenu.results.entities | first -%}

{%- if DEBUG -%}
<pre class="hit-nav-debug-pre">
NAV DEBUG (HEADER)
path={{ request.path | escape }}
menuFound={% if menuRecord %}YES{% else %}NO{% endif %}
</pre>
{%- endif -%}

{%- if menuRecord == nil -%}
  {%- if DEBUG -%}
    <div class="hit-nav-debug-note">
      NAV DEBUG: No active header menu found.
    </div>
  {%- endif -%}
{%- else -%}

  {%- assign menuId = menuRecord.hit_webnavmenuid | append:'' -%}

  {%- comment -%}
  Fetch menu items (Platform Route + CMS fallback joins)
  {%- endcomment -%}
  {%- fetchxml navItems -%}
  <fetch mapping="logical">
    <entity name="hit_webnavmenuitem">
      <attribute name="hit_webnavmenuitemid" />
      <attribute name="hit_displaylabel" />
      <attribute name="hit_name" />
      <attribute name="hit_sortorder" />
      <attribute name="hit_parentmenuitem" />
      <attribute name="hit_url" />
      <attribute name="hit_platformroute" />
      <attribute name="hit_webpage" />

      <filter>
        <condition attribute="hit_isactive" operator="eq" value="1" />
        <condition attribute="hit_webnavmenu" operator="eq" value="{{ menuId | escape }}" />
      </filter>

      <order attribute="hit_sortorder" descending="false" />

      <link-entity name="hit_platformroute"
                   from="hit_platformrouteid"
                   to="hit_platformroute"
                   alias="r"
                   link-type="outer">
        <attribute name="hit_physicalpath" />
        <attribute name="hit_queryparameters" />
        <attribute name="hit_name" />
      </link-entity>

      <link-entity name="mspp_webpage"
                   from="mspp_webpageid"
                   to="hit_webpage"
                   alias="wp"
                   link-type="outer">
        <attribute name="mspp_partialurl" />
      </link-entity>

    </entity>
  </fetch>
  {%- endfetchxml -%}

  {%- assign items = navItems.results.entities -%}

  {%- if DEBUG -%}
  <pre class="hit-nav-debug-pre">
NAV DEBUG (ITEMS)
menuId={{ menuId }}
itemsCount={{ items | size }}
  </pre>
  {%- endif -%}

  <ul class="hit-nav__menu" role="list">
    {%- assign rootCount = 0 -%}

    {%- for item in items -%}

      {%- assign parentId = '' -%}

      {%- comment -%}
      Prefer lookup object id when available.
      Do not rely on linked parent aliases for root detection here.
      {%- endcomment -%}
      {%- if item.hit_parentmenuitem -%}
        {%- if item.hit_parentmenuitem.id -%}
          {%- assign parentId = item.hit_parentmenuitem.id | append:'' | strip | downcase | remove:'{' | remove:'}' -%}
        {%- else -%}
          {%- assign parentRaw = item.hit_parentmenuitem | append:'' | strip -%}

          {%- comment -%}
          In Power Pages, an empty lookup can sometimes stringify oddly.
          Only treat it as a parent if it resembles a GUID.
          {%- endcomment -%}
          {%- if parentRaw contains '-' -%}
            {%- assign parentId = parentRaw | downcase | remove:'{' | remove:'}' -%}
          {%- endif -%}
        {%- endif -%}
      {%- endif -%}

      {%- if parentId == '' -%}
        {%- assign rootCount = rootCount | plus: 1 -%}
        {%- include 'components--web-nav-header-node'  item:item  allItems:items  maxDepth:4  depth:1  trail:'' debug:DEBUG -%}
      {%- endif -%}

    {%- endfor -%}

    {%- if DEBUG -%}
      <li class="hit-u-hidden">
        NAV DEBUG: rootCount={{ rootCount }}, itemsCount={{ items | size }}
      </li>
    {%- endif -%}

  </ul>

{%- endif -%}

END OF ORIGINAL MENU CODE
{%- endcomment -%}"
}
